while (true) {
  if (sensorCarro.temCarro) {
    portao.abrir();
    luz.ligar();
  } else {
    portao.fechar();
    luz.desligar();
  }
  esperar(100);
}

let abertaPor = 0;
forno.assar(3000);
while (true) {
  if (geladeira.portaAberta) {
    if (abertaPor > 2000) alarme.tocar();
    abertaPor += 100;
  } else {
    abertaPor = 0;
    alarme.parar();
  }
  esperar(100);
}

while (true) {
  let verdePor = 0;
  while (!botao.pressionado && verdePor < 5000) {
    esperar(100);
    verdePor += 100;
  }
  semaforo.mudar("amarelo");
  esperar(1000);
  semaforo.mudar("vermelho");
  esperar(2500);
  semaforo.mudar("verde");
}

while (true) {
  if (sensorUmidade.valor < 30 && sensorDia.dia) {
    aspersor.ligar();
  } else {
    aspersor.desligar();
  }
  esperar(100);
}
